/**
 * - `invitation.not-found`: no invitation with this id, or no verified address of the actor in
 *   the directory yet;
 * - `user.not-found`: the `userId` of the path is not the actor.
 */
export type InvitationOrUserNotFoundResponse = Problem;

/**
 * `invitation.answered`: the invitation was accepted or refused already, with `details.status`.
 */
export type InvitationAnsweredResponse = Problem;

/**
 * `invitation.revoked`, or `invitation.answered` with `details.status`.
 */
export type InvitationClosedResponse = Problem;

/**
 * `invitation.daily-limit-reached` when the requested emails exceed the sender's or
 * organization's rolling allowance. `details.remaining` is the smaller allowance
 * remaining. `details.nextAvailableAt` reports when the limiting allowance next grows or
 * when both will have grown if they are equal. `Retry-After` is the delay in seconds.
 * Nothing was created, sent or emitted.
 */
export type InvitationBatchLimitedResponse = Problem;

/**
 * - `invitation.resend-throttled`: the email of the invitation went out less than an hour
 *   ago; `details.resendAvailableAt` is `sentAt` plus one hour;
 * - `invitation.daily-limit-reached` when the organization or sender has no invitation
 *   email left in their rolling allowance. `details.remaining` is `0` and
 *   `details.nextAvailableAt` reports when both allowances permit another email.
 *
 * `Retry-After` is the seconds until the resend can succeed. Nothing changed and nothing was
 * emitted.
 */
export type InvitationResendLimitedResponse = Problem;

/**
 * `invitation.revoked`, `invitation.answered` (with `details.status`, `accepted` or
 * `refused`) or `invitation.expired` (with `details.expiresAt`).
 */
export type InvitationNotPendingResponse = Problem;

/**
 * `invitation.revoked`, `invitation.answered` (with `details.status`, `accepted` or
 * `refused`), `invitation.expired` (with `details.expiresAt`), or
 * `organization.seat-quota-exceeded` when acceptance would add a seat beyond the plan limit.
 */
export type InvitationAcceptanceConflictResponse = Problem;

/**
 * `organization.seat-quota-exceeded`: changing this guest to an admin or a member would add a seat beyond the plan limit.
 */
export type SeatQuotaExceededResponse = Problem;

/**
 * `member.owner-protected`: the owner is neither removed nor given another role.
 */
export type OwnerProtectedResponse = Problem;

/**
 * `organization.slug-taken`: another organization uses the address, with `details.slug`.
 */
export type SlugTakenResponse = Problem;

/**
 * - `organization.slug-invalid`: the address derived from the name has fewer than 2
 *   characters, with `details.slug`.
 * - `organization.slug-reserved`: the address, given or derived, is reserved by the `Slug`
 *   schema of `openapi/public/organizations.yaml`, with `details.slug`.
 */
export type SlugInvalidResponse = Problem;

/**
 * `organization.slug-reserved`: the new address is reserved by the `Slug` schema of
 * `openapi/public/organizations.yaml`, with `details.slug`.
 */
export type SlugReservedResponse = Problem;

/**
 * `request.version-mismatch`: `If-Match` is not the current version, with `details.version`.
 */
export type VersionMismatchResponse = Problem;

/**
 * Opaque authenticated cursor returned as `nextCursor` by the preceding page.
 */
export type IdentityMembershipCursorParameter = string & string;

/**
 * `"<version>"` the change was made from.
 */
export type IfMatchParameter = string;

